// Keys: project.slug. If a slug is missing, the IT text is used as fallback.

export interface ProjectI18n {
  titolo?: string;
  sottotitolo?: string;
  descrizione?: string;
}

export const projectsI18n: Record<string, ProjectI18n> = {
  "it-finale-emilia-mo-titan": {
    titolo: "THE PATIO OF IDEAS",
    descrizione: "The new outdoor areas of the Titan Italia company were designed in the zone facing the access to the new offices. The project involves 15 new internal parking spaces and 10 external ones. The area in front of the offices is characterised by a chequerboard pattern alternating paved areas in white concrete with green areas. Each green area has been planted with manna ash trees, and a cherry tree marks the largest one. A series of ground-level lights traces the path during night hours. The fence alternates solid concrete sections with zones of vertical metal candles that filter the new building and allow the greenery to spill out, defining the external parking areas."
  },
  "it-finale-emilia-mo-titan-2": {
    titolo: "THE PATIO OF IDEAS",
    descrizione: "The project is located at the Titan Italia company in Finale Emilia (MO). The brief was to design new executive office spaces inside a recently built shell building adjacent to part of the production area. The intervention took place within a prefabricated structure whose façade already featured a defined perspective design. As a consequence, the interior spaces had to be adapted to the existing openings. The new project unfolds over three floors for a total net area of 1,200 m² and faces outward on two sides of the building, east and south. This limited exposure was initially a design constraint, since it made it impossible to bring light to the west and north zones of the structure. The problem then became the theme of the project. A large internal courtyard was created, which made it possible to exploit even those surfaces originally without windows. Structurally, to open up this void, several roof and second-floor slab beams had to be removed.\n\nCompositionally, the ground floor is divided into three bands: two perimeter strips devoted to offices and a central service core (reception – waiting area – meeting room – changing area) around which it is possible to circulate. The ground floor is directly connected to the production area and to a testing laboratory. A main staircase and a lift lead to the upper two floors. The first and second floors feature the central courtyard, overlooked on three sides by the offices and on one side by the production area. A horseshoe-shaped distribution corridor adjacent to the courtyard connects all the rooms. A raised area with a tiered step provides access to the inner garden and to the meeting room, which is fitted with glazing onto the courtyard and the corridor.\n\nThe intervention reveals the existing prefabricated structure as much as possible to justify the typology of the operation. This was achieved by emphasising all structural elements with a black colour. Chromatically, the entire project relies primarily on blacks and whites with some brown accents. The partition walls between the production and testing areas use an exposed sound-absorbing material of wood and cement. Part of the furniture — reception, changing area, cabinets and fan-coil boxes — was custom-made, mainly in MDF. Jasmines and Cercis Siliquastrum populate the courtyard in large planters."
  },
  "it-ferrara-studio-di-architettura": {
    titolo: "DARE-ARCHITETTURA",
    descrizione: "The intervention concerns the conversion of a space formerly used as a garage into an architecture studio. The studio is located in part of the historic city, in an area once known for its crafts activities. The studio-atelier consists of a single space with an adjacent bathroom. A custom-made iron bookcase houses three tables that can be repositioned according to the studio's needs. The flooring in the work area is entirely in calamine iron, in harmony with the bookcase element. The bathroom features a floor in OSB painted grey. New plasterboard walls partially clad the perimeter masonry, creating a recess for perimeter strip lighting."
  },
  "it-calto-ro-uffici-direzionali": {
    titolo: "ELETTROSTAR",
    descrizione: "The client's requirements were for new executive offices for the company, with the need for direct contact between workers in the production area and those inside the offices. The office building sits within an existing industrial shed in the south-west wing. It is built on the footprint of the previous office space but with a greater extension. The new building is arranged over two floors. The ground floor houses an entrance hall with waiting and secretarial areas, an adjoining hallway and a bathroom with antechamber. The hall provides direct access to the production area of the shed, from which the changing rooms and bathrooms for employees can be reached. From the entrance hall, a calamine iron staircase leads to the first floor. Here, three office spaces are connected by a corridor that faces the production area through a glazed wall, ensuring an ongoing relationship between the production and office areas. One office is equipped with a storeroom. All rooms are fitted with heat-pump air-conditioning systems."
  },
  "it-modena-logo-musei-qualita": {
    titolo: "CONFRONTATIONS",
    descrizione: "...a person stands at the mirror... a person looks at another person... two people are on a train with a window behind them... two people exchange a few words... they might see each other, or they might not... it could suggest distance... a father tries to speak to a child... what they hear versus what they see... two heads are talking... they are talking and looking at each other in the mirror... two sad faces gossip... the shadow... a confrontation... tension... it conveys dialogue... communication... explanation... tranquillity... harmony... difficulty in communicating... an adult tries to speak with a child... different forms of communication for the two, hampered by the obstacle... two people observe something... they could be looking at themselves in the mirror and seeing themselves... there is a transfer of information... two people look at one another... stillness... a mirror... the projection of something larger onto something smaller... a person speaks to themselves... one speaks and the other is the dark reflection... one is the hidden part and the other the visible one... it suggests humanity, dialogue, communication... the logo of a book on history, humanities, psychology... man looks within himself... in museums there are works made by us, so we see what we are... what we have invented... they are identical, symmetrical as if before a mirror... they evoke an inner confrontation... necessarily it is the same person looking at themselves in the mirror... a confrontation with oneself... a confrontation with oneself in which one part is dominated... a deep part and a superficial part of the same person... two heads of a statue... two profiles... a gentleman, a lady... two bald profiles saying nothing... two prisoners talking... it is a mirror... two trees... I look inside myself... the present looks at its past... the limit seeks its fullness... the man who looks at art... the art that awaits him... a perspective... two bedside lamps..."
  },
  "it-castelmassa-ro-profumeria": {
    titolo: "GOLD",
    descrizione: "The project involves the recovery of an old commercial space, converted into a shop selling perfumery and costume jewellery. The intervention required a redesign of the interior spaces and the bespoke design of the furniture. The only element retained from the previous space were the shop windows. These became the starting point for developing the new colour palette of the interior furnishings. Part of the furniture was developed in gold tones to harmonise with the dated gold-anodised frames. The furniture was made partly in full-paste white laminate and partly in Corian. Neon and halogen lights were installed in relation to the objects on display. All new horizontal and vertical partitions were built in plasterboard. The flooring was finished with two-component paint embedded with gold glitter."
  },
  "ampliamento-cimitero-zevio": {
    titolo: "THE PALM OF FORTUNE",
    descrizione: "The project foresees the construction of a new extension volume whose footprint lies between two existing buildings. Complete demolition of the ramp and the tiered steps on the footprint — both belonging to the two adjacent buildings — will be required. The new intervention faithfully follows the compositional aspects of the two neighbouring buildings. The layout will appear symmetrical, with central niches and a double lateral vestibule. Below, a base (partly semi-basement) finished with bush-hammered Verona red marble cladding will house 5+5 family tombs of 8 bodies each, each with its own masonry subdivision, for a total of 80 burial places. The vestibule, set at 1.6 m above ground, will be marked by two columns and will serve partly as access for lowering coffins into the family tombs — via 5 hatches on each side — and partly as a distribution area for the remaining niches. These covers can be temporarily removed and, using a coffin-lowering device, individual burials can be carried out within the family tombs."
  },
  "codigoro": {
    titolo: "TARTAN",
    descrizione: "The commission involved extraordinary maintenance of the façade for energy upgrading and to resolve previous water infiltration. The project foresaw the complete demolition of the previous brick cladding and stone string courses, as well as of the existing frames. The new composition was conceived with the intention of preserving the existing horizontal partitioning of the base and the two upper floors being refurbished, while creating a new verticality of the façade through the insertion of vertical chamfers and new recesses that further mark the rhythm of the windows. The new cladding was carried out with an external thermal insulation system finished with thin plaster. The frames were conceived as a single entity, in order to create metal frames that cantilever out from the façade. The frames are entirely concealed-frame single-sash. Even the blind frames are concealed, creating a larger glazed surface than before. Delicate parapets complete the façade detail."
  },
  "it-carpi-scala-vvf": {
    titolo: "VVF CARPI",
    descrizione: "The commission entailed designing a new volume to house a fire-escape staircase, in order to meet the requirements for escape routes in case of fire for a hospital wing. The structure is built entirely with galvanised metal profiles. There are four floor slabs in addition to the ground slab, made of a composite slab on exposed corrugated metal sheet. The structure was then \"dressed\" with a modular skin made of expanded aluminium mesh panels in light grey, in order to blend with the tones of the existing concrete string courses of the adjoining building. The façade panels are riveted to the structure via vertical omega profiles. Horizontally, they mark the various interfloors, creating openings within. These openings serve both to evacuate smoke more quickly in case of fire and to provide views onto the interfloors and the stair well."
  },
  "it-pompos-iat-info-point": {
    titolo: "IAT",
    descrizione: "The commission involved the design of furniture/fittings to be placed within the building known as the Former School – Tourist Information Office, inside the museum complex of Pomposa.\n\nGROUND FLOOR\nThe office space will host an info-point area to welcome tourists and provide them with information. The area will be furnished with an L-shaped counter. Behind the counter, dedicated storage furniture for documentation is planned. A wall-mounted display and a column display will be positioned near the office area. All the furniture will be custom-made in Valchromat MDF coloured in two shades. A full-height MDF wall will enclose a small office workstation. The wall can be opened and closed depending on need, with a bi-fold panel system featuring a rotating door.\n\nFIRST FLOOR\n1 museum configuration\nThe first will be equipped with 7 wheeled display panels with hooks for hanging exhibition panels. The arrangement of the 7 panels forms a fully enclosed central space where the chairs used in the conference configuration are stacked.\n2 conference configuration\nThe second configuration uses the 48 conference chairs, and the 7 display panels are placed at the entrance of the hall, serving as coat-stands thanks to a series of steel hangers of various sizes attached to the top of the panel."
  },
  "it-firenze-fountain": {
    titolo: "MELTING POINT",
    descrizione: "From the earliest stages, the goal of the project was to bring contemporaneity to the historic Piazza del Carmine in Florence. Contemporaneity is pursued both in design and in theme. Piazza del Carmine is one of the four great squares facing the churches of the four mendicant orders that settled in Florence in the 13th century. These squares have undergone major transformations over the centuries, but Piazza del Carmine has remained almost intact. The new project transforms the square radically. The grove creates a backdrop on the urban front, providing shade to a space previously monopolised by cars. Each tree has been adopted by a class of the Machiavelli middle school. The theme of adoption is paired with another theme just as resonant for our time: integration and multi-ethnicity. Cities and squares are increasingly places of dialogue between different cultures that meet and enrich one another. The project aims to symbolise this shared space among ethnicities through the use of vertical elements of different heights and colours, evoking integrity and conviviality. To this end, the grove is ideally extended through a grid generated by the layout of the trees. Vertical elements are installed on this grid; one of them, marked by the paving, is the drinking fountain. The shade of the trees and the freshness of the drinking fountain thus shape a contemporary space in the new Piazza del Carmine — a space that speaks of respect for nature and for the human being."
  },
  "it-brunico-bz-asilo": {
    titolo: "EISKEILE",
    descrizione: "The site of intervention lies within the Municipality of Brunico. San Giorgio, the competition site, is part of a mountain landscape and remains one of the most anciently inhabited locations in South Tyrol, as evidenced by the remains of hill forts. The pragmatism of these territories makes it well known that school space cannot be considered solely as a physical envelope, but rather as an educational, social and protective space. The quality of the spaces will depend on architectural factors such as the form of the spaces, their organisation, and the sensory perceptions linked to light, colour, sound and tactile suggestions.\n\nWe therefore proposed a project that reflects in its forms the concept of a local architecture — that of the castles, whose defining feature is a defensive curtain wrapping and protecting the buildings. The design idea proposes an architecture that develops from a protective enclosure, drawing and shaping the slopes of the volumes within, generating pointed forms. The intent is to evoke great wedges of ice, integrating the project both visually and architecturally with the surrounding landscape. An enclosure with openings allows the life of the school to permeate and dialogue with the outside, while at the same time conveying a sense of protection for the children.\n\nThe layout consists of five volumes which, through large glazings, face four separate green areas. All the buildings are connected by a two-storey volume that acts as the fulcrum, taking on the value of a recreational space that — both formally and socially — unites and blends the various school activities. Each individual building contains a section with its own group-activity room and cloakroom, connected to a dedicated green area. To stimulate sensory perception, each section was conceived in a different colour. Outside the enclosure, near the road, is the staircase rising from the underground parking — an area which also includes the driveway access to the kitchen's storage."
  },
  "it-castelmassa-ro-negozi": {
    titolo: "THE ARTISTS' UMBRELLA",
    descrizione: "The site of intervention is located on Via Antonio Pacinotti in Castelmassa (RO). It sits within a context featuring two buildings formerly used as a covered market. Pavilion A, recently refurbished, and Pavilion B. The refurbishment is proposed for the entire block through the rearrangement of roads and parking areas, and through the redevelopment of Pavilion B, where the roof structure design must be preserved.\n\nUnder the covered area, the new building is inserted as a completely independent element, echoing the old function of the pavilion as a shelter for commercial activities. The building unfolds over two levels. Inside, it accommodates five commercial spaces of various sizes. The spaces are arranged on two levels, with the possibility of a mezzanine, and bathrooms for each individual unit. Large glass walls identify each commercial activity on both the ground and first floors. Externally, the building features two materials on its façade: glass and wood.\n\nThe non-glazed surface is clad in wooden battens to minimise environmental impact, harmonising with the park setting. We thus work with a fully renewable material that resonates with the park in which the pavilion sits. An outdoor paved corridor distributes the commercial spaces and connects to the eventual access to Pavilion A. At the junction between Pavilions A and B, a canopy is placed. Steps and outdoor cycle-pedestrian areas complete the exterior. A series of spotlights installed in the original concrete plinths of the steel structure illuminate the pavilion's old wooden roof."
  },
  "it-auronzo-bivacco-fanton": {
    titolo: "WAYMARKER",
    descrizione: "1 – ARCHITECTURE The site of intervention is crossed by hiking trail 280, which runs from the current Fanton bivouac up to the Forcella Jau della Tana saddle. A hiking trail is a path without technical difficulties, mostly corresponding to mule tracks built for agro-silvo-pastoral or military purposes, or to access paths to refuges, or to connections between valleys. It is the most widespread and most travelled type of trail, representing 75% of the itineraries of the entire organised trail network. All CAI trails are marked along their route with white-and-red waymarkers that act as a true \"Ariadne's thread\". There are two types of waymarkers: vertical or horizontal. The first is generally an arrow-shaped sign — white (or wood-toned), with a red tip and a white-and-red tail. It indicates the direction of the destination(s) of the trail and the time required for an average hiker to reach them. On the tail, in the white area, the trail number is indicated. They are found at the start of the route and at major junctions. The second is painted on natural elements such as rocks or tree trunks. It is used to mark the continuity of the trail; it is placed near junctions and every 200–300 metres if the trail is clear, otherwise more closely, taking into account environmental features and respectful integration into the place. Our intervention strategy proposes an architectural element in natural guise that acts not only as a shelter.\n\n2 – SUSTAINABILITY We believe that a project can be considered sustainable when it is capable of self-maintaining and when it can transmit and generate comfort. The orographic conformation of the terrain led us to study the volume taking into account solar radiation and winds. We sought to conceive a volume capable of achieving maximum energy efficiency while also providing feelings of pleasure and relaxation for hikers resting inside. We chose to use sustainable, natural materials such as wood, wood fibre, plywood and steel; these materials are long-lasting, require little maintenance and respect the environment. As for the bivouac structure, the initial design strategy was oriented toward X-LAM technology, but after careful calculations it was clear that this would not be the most economical or the simplest solution to build; it would have been more expensive both for the panel costs and for helicopter transport. Therefore, for economic sustainability, we opted for a timber-frame structure, lighter so as to allow assembly far from the site and helicopter transport in a single trip, avoiding excessive costs and limiting environmental impact. We also felt it appropriate to make the architectural object energy-self-sufficient, using solar radiation via a photovoltaic system capable of generating enough energy for interior lighting and for the operation of a satellite camera for the remote monitoring of the bivouac."
  },
  "it-ferrara-parcheggio-biciclette": {
    titolo: "BLU CARPET",
    descrizione: "The building to be redeveloped sits on an area that will act as a connection-filter between the Corso Isonzo traffic artery and the future ex-MOF square. The new masterplan provides that access to the square will occur only via a driveway serving the new residences and via the pedestrian area developing from the Darsena. Maintaining the old perimeter wall would therefore create a barrier. The removal of the wall and the insertion of longitudinal green strips serve the dual function of organising the area through a unified design and rendering it permeable to cycle-pedestrian mobility, through transverse paths from Corso Isonzo to the ex-MOF square. External access to the square is provided by safe, direct paths, while accessibility is guaranteed by a ramp that overcomes the level difference of the raised ground floor of the building.\n\nExternally, the building will be preserved in its current form, recovering and upgrading its existing architectural elements. Only the tower will feature a new extension at its top. The existing plaster will be restored using the external thermal insulation system, thereby improving the energy performance of the envelope.\n\nInside, the entire spaces will be rethought and adapted to the new objectives of the brief, taking into account and bringing back to light the two frescoes by Cattabriga, and refurbishing part of the existing ground floor paving. To enhance the building's capacities, it became necessary to open three sunken courtyards in the external area belonging to the early-twentieth-century building. This action made it possible to meet the natural lighting, ventilation and microclimate requirements needed for the future co-working and association spaces in the basement floor. Internal accessibility is guaranteed by mechanical vertical-connection systems."
  },
  "it-castelmassa-ro-cimitero": {
    titolo: "THE CONTEMPORARY FRAME",
    descrizione: "The municipal commission asked for a rethinking of the new entrance to the current cemetery, with the aim of mending all those incongruous additions that had pushed back the historic entrance, causing it to lose its importance, and then of accommodating 60 new burial niches. The project for the new cemetery entrance, together with the new square, mends the past extensions, identifying and honouring the now-receded historic access. The new portal, with its architectural scale and monumentality, frames the dated portal, giving it new life.\n\nThe entire façade and square appear completely white, the colour of purity. White ceramic slabs on the walls and white washed pebbles on the floor are the materials used. Only one face of the portal will be marked by reddish rust tears capable of expressing the theme of suffering. An architectural element unwinds from the square, edging it as far as the portal, creating benches and bicycle parking areas.\n\nThe building hosting the 60 new niches takes into account particular functional considerations addressed to elderly users. Access to the upper niches can take place without the help of the well-known \"metal ladders\", but rather via a covered and illuminated flight of stairs. The use of two different shades of material identifies the burial zone. Stainless steel tombstones and LED votive lights complete the cemetery furnishing."
  },
  "it-ferrara-obitorio": {
    titolo: "THREE FINGERS",
    descrizione: "An initial analysis of the project site highlighted a strong inconsistency among the architectural languages of the existing buildings to be refurbished. The proposal for the new Cittadella del Commiato in Ferrara consists of unifying — within a single architectural language — the existing buildings constrained to partial renovation and the new expansion volumes. The unifying architectural element is a steel skin which, starting as a new roof for the existing buildings, becomes the architectural façade element for the new expansion volumes. A further design choice was to keep the expansion volumes detached from the existing building and to set them at a height of 3.5 m to expose as much as possible the current historic façade.\n\nFunctions – The new project pursues a clear separation between the spaces dedicated to mourners (public) and those dedicated to the staff of the various mortuary activities (private). The existing building, subject to partial renovation, hosts the body-observation and cold-storage functions and is directly linked to the mortuary area via a central distribution node containing a staircase and a goods lift that connect to the remaining mortuary areas on the first floor and to the body-recomposition area on the basement floor. The basement floor connects the mortuary area to the existing building, from which — via a further goods lift — the coffins arrive with their floral arrangements. The recomposition area on the basement floor links via the existing well to the area of the funeral chambers. The well functions as a coffin lift. Indeed, the recomposed body, once reaching ground level, can then be placed directly into the appropriate funeral chamber. Each funeral chamber contains a small private worship area to be arranged differently according to the religious affiliation of the deceased. An area of over 100 m² connected to the funeral chambers and facing the mourners' entrance square serves as a refreshment area for relatives and amenities. The vehicle-washing area is located in the newly built west wing, together with the technical rooms.\n\nThe design choice was to leave all the existing functions of block B, owned by AMSEF, unchanged. The minor intervention consisted exclusively in repositioning the bathrooms and creating the connection (stairs and lift) between building B and the basement.\n\nMaterials – Two main materials are used. The existing brick of the old buildings is brought back to light and contrasted with a new material, titanium-zinc, which will envelop all the new volumes and become the roof of the entire project. All glazed areas use translucent glass to allow diffused light into the work and refreshment spaces. The five funeral chambers are conceived in concrete with a large glazed opening at the top oriented southward, so as to bring light onto the coffin.\n\nSustainability – The well within the project area, beyond being the element raising the deceased to the funeral chamber, also becomes an architectural-functional element for rainwater collection, which is gathered in a dedicated cistern and reused in the building's bathrooms. Long translucent glazings to the south bring light into the mortuary spaces and corridors, increasing comfort in the work areas in terms of both temperature and luminosity."
  },
  "it-ferrara-parcheggio-biciclette-2": {
    titolo: "Bicycle parking",
    descrizione: "Ferrara \"city of bicycles\" — this is what one reads when a tourist arrives in the city and what they expect to find on visiting it. Now let us try entering \"Ferrara city of bicycles\" into a web search engine: what we find are photographs of the current bicycle parking area next to the station. The real calling card, however, comes when the tourist steps off the train and through the exit of the station. A quick glance to the left immediately confronts them with the obsolete reality of a pile of bicycles — ready for the scrap heap — chained one on top of the other with no way out. Perhaps there is a need for a better icon — one that identifies the city for what it is actually described to be, and that makes the exchange between public transport and bicycle more functional. Let us therefore allow the visitor to rent a bicycle and the resident to park their bicycle in a safer place sheltered from the rain. Showing that Ferrara is striving to create urban sustainability devoted to ever-greater bicycle use, while at the same time allowing bikes to be stored in an orderly manner within a structure."
  },
  "it-libano-bl-scuola": {
    titolo: "Libano school extension",
    descrizione: "Climate analysis was the starting point for designing the school extension in order to classify it as sustainable architecture. Sustainability does not mean exclusively the installation of technological systems that reduce energy consumption, but rather designing while taking into account the climatic conditions of the place (solar radiation, wind, temperature), so as to extract the best benefits and produce a building in which the people who use it can live in a healthy and efficient manner. A second analysis was carried out on the morphology of the ground, which features a level difference between the existing ground around the current school and the ground at the southern boundary of the site. This level shift of 1.35 m made possible an intervention in which the new building is partly underground. This approach led to a volume above ground of 400 m³ — half of the above-ground volume requested by the brief, which was 800 m³ — thereby clearly limiting the environmental impact on the surroundings. The volume was therefore partially buried, allowing the roof of the new building to be used as a green area for \"botanical gardens\", with consequent improvement of the summer climate in the new pole's interior spaces."
  },
  "it-tolentino-uffici-comunali": {
    titolo: "RED DIAMONDS",
    descrizione: "Through an analysis of the architectural morphology of the town of Tolentino, a fragmented skyline quickly emerged — shaped along multiple pitched roofs of varying slope and rising occasionally with towers and bell towers of great architectural value (Basilica of San Nicola, 13th century, and Castello della Rancia, 1357). The new design proposal seeks to extend this morphology to the urban zone of the city (the competition site) classified as \"industrial\", attempting to integrate it with the morphological lines of the \"historic centre\". A single line, a single material that in their minimality form three towers connected to one another like three large red diamonds: this is the new proposal for the new municipal offices building. Three distinct and highly visible towers connected by two fully glazed \"filters\" with an opaque surface (volume marked in orange). Access to the building for the public and for municipal employees occurs at the intersection zones (filters) between the 3 towers (areas marked in red) via two entrances (A-B) leading directly to a wide entrance hall, which is directly connected to two staircase/lift cores rising to the upper floors. The entrance hall also provides employee access to the storage and changing areas. Technologically, the building is classified as \"passive\", since thanks to a careful study of the south façade the heat provided by solar gain — through 2 large solar greenhouses (towers A and C façades) and a photovoltaic area (tower B façade) — can cover all the energy required for winter air-conditioning, electricity generation and domestic hot water production."
  },
  "nl-delft-universita": {
    titolo: "LET'S SQUARE",
    descrizione: "The basic idea of the project is to create a building whose architectural composition can satisfy certain requirements imposed by the local climate. The starting point is the idea of creating a square as a meeting point for students. To be lived in, however, the square needs to be covered, given the heavy annual rainfall in the Netherlands. The building thus appears as a large umbrella-plate supported by three functional blocks, creating an entrance-square beneath as a meeting and shelter point. The three blocks house classrooms, laboratories, a restaurant and an auditorium. The large raised plate, in turn, serves as a library and study area."
  },
  "it-torino-uia-info-point": {
    titolo: "HUB",
    descrizione: "HUB: a place where people meet and activities circulate, and where movement becomes the essence. Creating a place where people can meet. The info-point was designed with great flexibility of use in mind. It can become a venue for concerts, a conference area, or an exhibition hall. This high degree of flexibility is made possible by the use of furniture that can take on various functional configurations. The info-point, mainly built in wood, is compositionally pierced by a large window forming an exhibition stage clad in a steel skin. The stage can be closed off with glazing. The choice to create a covered area was driven by the need for shaded zones. The building meets eco-sustainability parameters, being made entirely from recyclable materials such as wood, glass and steel. Assembly and dismantling of the info-point are easy thanks to a special joint system."
  },
  "ir-dublino-u2-landmark-tower": {
    titolo: "U2 landmark tower competition",
    descrizione: "The site in question is the former port area of Dublin. These docklands historically hosted port and industrial areas. Today an agency has been established to redevelop these marginal areas, the Dublin Docklands Authority. The latest urban plan drawn up by the agency established a regular grid for the dock in question — partly for social housing and partly for commercial spaces, plus two waterfront paths — specifying that the headland would take on a different character. This headland became the subject of the \"U2 Landmark Tower Competition\". Hence the need to treat the theme of the paths with the building itself, which becomes a true building-path. It allows one to connect the Liffey waterfront with the Grand Canal Dock waterfront and to reach the opposite bank of the lot. The building will appear as the natural connection between the two existing paths, ensuring users continuity of travel and, among other things, a visual perception of the entire basin at a height varying from 0 to 4 metres."
  },
  "it-salerno-colle-bellaria": {
    titolo: "LEITMOTIV",
    descrizione: "Analysing the urban fabric of the historic centre of Salerno, it emerged that the existing pedestrian routes external to the historic city are the one along the seafront (Lungomare Trieste) and the one running along the Irno river. Our intention is to connect the city centre with the Bellaria hill, since we believe that the hill should be made accessible on foot from the city. The idea is to enhance the stretch of Lungomare Clemente Tafuri up to the \"La Carnale\" fort. The fort, built in 1563, was historically an integral part of the Bellaria hill, closing off to the south the Irno valley where the central settlement of Salerno now stands. The recent construction of the SS18 state road and the railway has divided the hill in two. The project therefore foresees a mending of the two elements by means of an elevated pedestrian connection between the seafront and the Bellaria hill, via a footbridge starting from the fort. A lift will bring people from the +56 m level of the fort up to +114 m, where the footbridge begins. From that height starts an evocative elevated route which, crossing the entire railway network and the part of 1970s development, reaches the lower belvedere of the Bellaria hill, from which the two paths into the park begin. Compositionally, the antenna takes shape from the square through the stacking of 50 rings of increasing section that generate a total rotation of 360°, rotating 7° relative to one another, eventually generating the form of a wind rotor at the top: like terraces set at different levels. The antenna's structural core will be built with a central reinforced concrete toroidal-section element with an external diameter of 3.5 m and a thickness of 1 m. At the upper part of the antenna structure, a vertical-axis wind rotor will be installed to convert wind energy into electricity."
  },
  "dk-copenaghen-europan-12": {
    titolo: "GREEN SHARING",
    descrizione: "Analysing the amount of public green space in the intervention site, we found an almost complete lack of it. Only around the intervention site could a few public green areas be found, such as the tree-lined avenue, the small Skydebanen park and Enghave Park. The remaining greenery is private. The Vesterbro district is composed of blocks which, by typology, feature private inner courtyards.\n\nTo increase public green space in the project site, we proposed opening up each block to create access points into the existing courtyards. The aim is to transform private courtyards into public-shared spaces. In this way we created a public green path that crosses all the courtyards, where people can meet and engage in shared activities. The access openings are located at the corner or on the side of each block. To allow these entrances to be opened, only a portion of the ground floor was demolished. The attempt was to preserve the authentic façades as much as possible. Since the building on the project site has high conservation value, our intervention left untouched the façades of the block with values 1 to 4. The only façade that was redesigned is the one at Dybbølsgade 11–13, with value 5.\n\nCopenhagen has a high rainfall regime, 50 mm on average per month, mostly during the summer and autumn periods. Our aim is to treat rainwater as a great resource. The intent is to collect as much rainfall as possible and use it for electricity generation. How can this be achieved? The challenge is to collect rainwater from the roof surface and store it in a tank placed on top of the roof. This creates a water reservoir possessing potential energy which, when descending, transforms into kinetic energy driving a turbine that generates electricity."
  },
  "it-san-gimignano-fascia-periurbana": {
    titolo: "CLODS",
    descrizione: "San Gimignano boasts great fame for its medieval towers that still rise today on its skyline. For this reason it has been nicknamed the \"Manhattan of the Middle Ages\". Of the 72 towers and tower-houses existing in the golden period of the Commune, 25 remained in 1850, and today only 16 remain, with others — truncated — still glimpsed within the urban fabric. The oldest is the Rognosa tower at 51 m, while the tallest is the Podestà tower, also called the Grossa tower, at 54 m.\n\nThe project proposal for the urban and landscape redevelopment of the town's peri-urban belt seeks to give new life to those 56 towers missing today. The entire project area is divided into 56 clods of different heights, each representing a missing tower. Each clod is perimetrically separated from the adjacent one, generating a series of irregular paths within the area, following the model of the medieval town. Overall, the intervention appears as an enormous earthen area furrowed irregularly to form numerous clods. A longitudinal furrow identifies the main path, running from Piazzale Martiri Montemaggio to Viale Garibaldi. This cycle-pedestrian path is irregular with a variable section, creating squares between the clods. It is a path parallel to the old Via Francigena that cuts across the new urban layout, connecting all the project's domains. It is fully accessible to people with disabilities. Perpendicular to the main path are secondary routes that on one side communicate directly with the historic streets of the medieval town, and on the other open into belvederes overlooking the agricultural garden. All paths are made of natural stone — Tuscan travertine — in different tonal gradations, identifying their hierarchy.\n\nAll the squares feature ribbons of green alternating with ribbons of stone that also become seating. Piazza Martiri Montemaggio, on its western side, has been entirely pedestrianised and connected to the new project square that hosts the new public buildings. In the residential area, a series of cube-like squares at various levels integrate with the volumes of the dwellings and with their respective private gardens. Along Via dei Fossi, a cycle-pedestrian path was secured and connected at many points to the new area.\n\nThe brief required the design of the peri-urban area west of the historic walls, divided into seven functional domains. The design approach was to unify the entire area with a single language and materials, while keeping the required functions of each domain distinct. The new area appears morphologically with irregular streets like the morphology of the medieval town. The buildings sit in direct contact with the paths, blending with them and forming a unified urban fabric. The project pursues a sustainable approach both in urban and social terms. Indeed, one can note the considerable area secured as public green space, with the insertion of urban vegetable gardens and the restoration of the olive trees. All car parks remain under green roofs, allowing a panoramic overview of the great peri-urban garden. The parking levels are connected by ramps.\n\nA series of ramps and steps create the new gateway connecting Via dei Fossi to the agricultural fields and, via a further path, to the old route alongside the cemetery, which then leads back up to Via dei Fossi by crossing the new green area with olive trees. None of the paths within the project allow car access at surface level, providing the citizen-tourist with a high quality of urban life. Only via a new circulation on the western side of the area is car access allowed for tourists reaching the parking areas. This made it possible to greatly increase what is defined as social sustainability — namely achieving and maintaining a healthy mix of socio-economic groups within the neighbourhood, reinforcing a sense of community to be passed on through the generations. When a sense of community is \"cultivated\" over several generations, the neighbourhood becomes self-renewing — and this is the true meaning of social sustainability. A variety of outdoor spaces determines quality for a wide range of users, fostering not only a social mix but also a generational one."
  },
  "it-chioggia-ve-laguna-lusenzo": {
    titolo: "LIVING ON THE EDGE",
    descrizione: "The intervention site subject to urban redevelopment lies within a lagoon context. It is located in the extreme southern part of the Venetian lagoon. We are therefore facing a continuous relationship between water and settlement, which led us to a strategic approach in which water, the calli, the squares and the new sea wall become the elements suturing the new dwelling with the built fabric along Madonna Marina. The project area lies between the Lusenzo Lagoon and the built fabric facing Madonna Marina road. From a morphological analysis of Chioggia and Sottomarina, we noted that both feature a dense comb-like urban layout perpendicular to the lagoon. Between built fabrics one finds a calle or a campiello. This led to a design approach for the new Ghezzi area through a series of \"strips of built fabric\" perpendicular to the lagoon, marking the new masterplan with a comb-like lagoon typology. Conceptually, the new project reflects a modern interpretation of the \"murazzo\". The Sottomarina murazzo historically had the function of protecting the city from floods coming from the sea. The \"new murazzo\" in question defends the park from the new vehicular artery, granting it a particular intimacy with the Lusenzo Lagoon. A park articulated from a sequence of green islands cut by water channels."
  },
  "it-ravenna-piazza-kennedy": {
    titolo: "THE ENCLOSURE",
    descrizione: "The area subject to the redevelopment intervention is located in the heart of the historic centre of Ravenna. The project presents itself as a contemporary re-reading of the various accretions that have characterised the history of the place. The following constituent parts emerge clearly:\n\n1) The Enclosure\nA contemporary revisitation of the perimeter wall, with which it coincides in plan, whose massive and urban importance is clear from the documents collected and from the historical photographs — historically delimiting the orchards/garden owned by the Rasponi family, marking the northwest front of the block known as the \"Jewish quarter\", and representing the built limit of the ancient church of Sant'Agnese and the convent for the city's parish priests, which was annexed around 1400.\n\n2) The Clock Tower\nThis strong design choice arises from the following considerations: meaning in relation to place — a representation of the passage of time as metaphorical signifier — at the point of the square with the greatest historical value.\n\n3) The Content: Paving and Greenery\nA contemporary revisitation of the historical stratigraphies relating to the pre-existences that characterised the space, using materials compatible with the typological, environmental, material and chromatic characteristics of the square."
  },
  "it-piacenza-punto-panoramico": {
    titolo: "STAIR OUT OF SCALE",
    descrizione: "The project arises from a surreal vision of a staircase rising toward the sky. An object — \"stair out of scale\" — that emphasises its surrealism still further, with the task of carrying you up to a panoramic viewpoint. The intervention strategy focused on making the panoramic point accessible and usable not only from the new ANAS bridge, but also from the embankment of the Piacenza bank. In this way, the floodplain area upstream and downstream of the bridge — which hosts a canoe club and a boat shelter — is revitalised. A series of wooden battens defines the paving connecting Via del Pontiere with the \"stair\" panoramic point, and through a sequence of branches it also connects the route with a possible Po riverside walk and with the green area downstream of the bridge hosting the boat dock. The project appears in perspective as a great staircase, which inside develops articulately with ramps and human-scale steps that allow one to climb up to the panoramic and restaurant point. The project was placed upstream of the bridge so as to privilege the north-west view from the panoramic-restaurant point but also from the numerous panoramic spots at varying levels offered along the \"stair\". Access to the panoramic point from the bridge is direct from road level via the pavement provided in the ANAS project. To allow cyclists access to the area, a parking spot for bicycles was provided as well as a traffic island enabling pedestrians to cross from the pavement downstream of the bridge to the one upstream. A careful design of the traffic island slows down vehicles near the pedestrian crossing. For appropriate landscape integration, wooden battens were used to clad the load-bearing structure designed entirely in steel. The use of wood harmonises the project with the landscape context of the Po."
  },
  "nl-emmen-europan-10": {
    titolo: "PARKLIFE",
    descrizione: "Analysis of the territory surrounding the project area immediately identifies a first problem: noise. To solve this first issue, the PARKLIFE project sets out to bring tranquillity and a feeling of calm across the entire area. This was achieved by immersing life within a park. The second problem of the area is the lack of a wall effect creating public spaces. This second issue was resolved by creating a ring surrounding the area and marking the boundary of the great green square.\n\nThe conceptual approach to the design can be summarised in two main elements:\n\n- PARK as a green lung for daily life, connecting the centre of Emmen via Wilhelminastraat. PARKLIFE gives the chance to live near the centre of Emmen while at the same time feeling immersed in nature. The green becomes the protagonist of the design and carries meaning as a natural element. A sequence of wind turbines scattered throughout the green area creates an effect like enormous flowers embracing the site. Passage through the park is allowed only by bicycle or on foot. Cars are forbidden inside the park. The houses are located across the park following an irregular scheme that recalls a natural and abstract composition. An irregular positioning of the buildings produces the unique feeling of the village.\n\n- RING as the park's boundary, in order to defend PARKLIFE as a barrier against the artificial noise coming from the roads and railway. The ring also acts as a filter, welcoming people into the park through six pedestrian and cycling entrances."
  },
  "it-abano-terme-boulevard": {
    titolo: "BOULEVARD OF THE THERMAL BATHS",
    descrizione: "An analysis of the urban fabric of the areas surrounding the project site and of the intervention area itself revealed that the dominant commercial activities are located along the existing promenade of Via delle Terme, adjacent to Piazza della Repubblica. Our proposal focuses on extending this promenade and maintaining adequate pedestrian safety along its full length, while allowing it to interact with all the commercial activities present in the stretch of the avenue covered by the competition. A central green boulevard is inserted into the project portion of Viale delle Terme, dividing the two traffic lanes for vehicles and bicycles. The boulevard becomes the new promenade, forming a \"green lung\" that — through \"arteries\" — connects each commercial activity along the road in an original and independent way. A central walkway is thus created, with an irregular section (from a minimum of 2.6 m to a maximum of 4.1 m), marked by wide horizontal bands that represent the connections with the shops for the users of the promenade, and slowing points raised by +5 cm for drivers. A double-length bench in marble grit, made of prefabricated elements, frames the pedestrian area — a place where one can stop and sit at any moment. At various points these long benches are interrupted to allow pedestrians to access the pedestrian zone or to cross toward the commercial activity facing the crossing. Each interruption of the bench, on its opposite side, is marked by a stone element bearing the sign of the commercial activity at the crossing."
  },
  "it-la-spezia-piazza-verdi": {
    titolo: "IMPRINTS",
    descrizione: "The project strategy moves from the historical analysis of the stratifications of La Spezia's urban fabric, seeking a re-interpretive key to the great linear, longitudinal city system — represented both by the road axis along which the intervention area develops and by the evocative re-reading of the architectural footprint of the former Politeama, working on the perimeter of the old foundations of the building below ground level. The level of the square is therefore lowered beneath the road level, creating an open-air artificial cavea on the foundation footprint of the nineteenth-century theatre. A public relational space allowing the differentiation of the pedestrian-public level from the vehicular one, which remains at the surface, decentred from the rectilinear axis. Ramps allow descent to the lower level of the new square, then re-ascent on the opposite side, avoiding crossing the road at grade.\n\nMusil said: what is great in man is that he is a bridge, not a goal... With the memory of this thought, we created a temporal bridge as a link between what has been and what can become... The memory of the Politeama theatre and its demolition... the recovery of a place where art created encounters between people and acted as social glue... On one side the architectural imprint — that of the Politeama — and on the other the imprint of the people who lived it... I imagined all those spectators seated, and I thought of creating their memory through a corporeal cast of some of them seated on the new stalls... I also revisited the actions of the artists and their sometimes ephemeral existence... and I thought of something more mysterious and impermanent, like a footprint left upon a shadow..."
  },
  "it-pontelagoscuro-fe-piazza": {
    titolo: "RE-COVER",
    descrizione: "(Re)thinking Piazza Buozzi as a real, concrete place of collective use, a shared space and beating heart of Pontelagoscuro. This is the idea behind the proposed project, which starts from a recognition of the history and peculiarities of the village and revisits them from a present, dynamic perspective. Functionality is the key term defining the project: redeveloping in order to unite different realities, to enhance existing architectural elements, to recreate a sense of intimacy and proximity — so that Piazza Buozzi may once again be not merely a place of transit, but an ideal space for the public and private activities that operate, and will operate, there. The dominant aesthetic element — a vertical paving made of 45 irregular modules recalling the events of the Second World War and Pontelagoscuro's will to rebirth — precisely emphasises, from a functional standpoint, the desire to join and bring closer the two fronts (north-south) of the square, and defines the different vehicular use areas. The recreation of a public space is further expressed in the expansion of the green area on the west side, where trees become both an enclosure and a permeable filter. Another founding element of the project is the desire to evoke the spirit of the ancient Via Coperta through light: a public lighting system that becomes a dynamic, enveloping aerial covering, offering an ideal space for itinerant commercial activities. The lampposts define a new \"uncovered cover\" space — a new Via Coperta built of arches of light. The fence of the elementary school on the north side of the square also becomes a long bench; the green spaces, places dedicated to leisure for young and old alike. (Re)giving identity to and restoring Piazza Buozzi to the inhabitants of Pontelagoscuro."
  },
  "it-ferrara-parco-massari": {
    titolo: "FREE PARCO MASSARI",
    descrizione: "Perhaps on misty Ferrara autumn evenings, the closing of the gates of Parco Massari still allows the ghost of little Maria Pristina Massari, only daughter of Duke Francesco, to wander freely among the colossal trees and the silent, solitary paths. Or perhaps the perimeter wall surrounding the green area is a kind of shared heritage of memory for all those who at least once took refuge there to skip school, or to shelter from awkward encounters with parents or teachers.\n\nAnd yet today Parco Massari — the largest of the public gardens within the city walls — is a space physically and conceptually hidden, still not fully \"accessible\" more than 70 years after the municipality acquired it for public use. The history of the park itself tells from the very beginning of a desire for closure: the land, around four hectares and adjoining the properties of the Counts Bevilacqua, was initially used as a vegetable garden, and only later transformed into a garden from 1780 by the will of Marquis Camillo Bevilacqua Cantelli, who entrusted the project to the Ferrara-based architect and painter Luigi Bertelli. The perspectival reproductions of the time depict this great green space and its avenues flanked by mythological statues, labyrinths, fountains, small temples, flower beds, greenhouses for preserving exotic plants and fruits... and a perimeter wall. Decorated with small columns, urns and vases, it opened in seven entrances — one of which is still visible today on Corso Ercole I d'Este, at the corner with Via Guarini. The wall remained a defining element even when, in the mid-19th century, the entire complex was acquired by Count Francesco Massari, who — beyond planting the famous Cedars of Lebanon known to all Ferrarese for their branches stretching as far as Corso Porta Mare — reorganised the garden in the English style, leaving Parco Massari a mythical, inaccessible place to its citizens until the aforementioned acquisition by the municipality in 1936.\n\nThe question the young architect Rudy Davi wishes to put to the citizens of Ferrara is precisely this: does the perimeter wall still have reason to exist? A historical derivation of the private nature of Parco Massari, he holds that it has today lost its \"protective\" functional nature and constitutes an obstacle to the view and to the free use of the park. Rethinking the park as the beating heart of the city centre; freeing the cedars, the yews, the oaks, the ginkgos, the hackberries, the plane trees and the paulownias; the woodpeckers, the great tits and the robins; the fountains and the avenues; the benches and the children's play areas. A park that no longer encloses something within itself, but opens, breathes, and lets itself be crossed, seen and lived by its citizens. A new lighting system, a more functional use of the spaces, in order to transform Parco Massari into a true urban oasis, free and permeable — the final step in restoring the area to its citizens, and a symbol of a green and sustainable Ferrara."
  },
  "nl-groningen-europan-9": {
    titolo: "LEGOPARK",
    descrizione: "The project has two main objectives. The first is to preserve the old port, and the second is to create a natural buffer. 1 The old port has been preserved as it is considered a reference point of the area, also of historical value. We decided to retain all the old walkways and the existing boats. The cross-section of the piers narrows at their end point, transforming into lamps. The latter do not serve only as beacons for boats crossing the channel but also as lighting highlighting the old dam. 2 The natural buffer (the entire green area) will increase the quality of living for the people inhabiting the new area. Moreover, it allows a continuous walk from west to east through the green area, as the new masterplan suggests. It follows the logic of the project, which is based on permeability. The wave element is also an attempt to give life to the park, with the possibility of separating walkable levels and creating overlooks onto the area. All the dwellings (the filter element) form a modular composition that includes various voids. These voids serve as connections between the surroundings and the green area. From a compositional standpoint, this project shows an appealing succession of standard modules."
  },
  "it-ferrara-casa-bagaro": {
    titolo: "CASA BAGARO",
    descrizione: "The renovation intervention takes place in a building located within the Addizione Erculea, the 15th-century urban plan of Ferrara. The building has undergone a complete revision — in its interior spaces, its structures, and its energy performance. The composition of the main façade was partially revisited to enable the construction of two new internal parking spaces, while keeping the openings of the remaining floors unchanged. The base finds its contemporary key in the use of resin, succeeding in preserving its architectural character and its hierarchy. The new façade is the result of an extensive cleaning and consequent revisitation of the architectural elements; the downpipes are integrated into the façade, the gutter is integrated into the upper cornice, and the window frames are entirely concealed, as are the blinds. Inside, two apartments were designed, each on two floors with a shared common entrance. The first apartment |A| is distributed between the ground and first floors. A terrace at the rear visually and directly connects the living area to the garden. The second apartment |B| is distributed between the second floor and the attic. A balcony on the second floor visually connects the living area with the garden. A semi-basement room with access to a harmonious private garden completes the spaces."
  },
  "it-ferrara-scala-montecatino": {
    titolo: "MONTECATINO STAIRCASE",
    descrizione: "The renovation takes place in the historic centre of Ferrara, and more specifically in the historic Palazzo Montecatino, built in the Renaissance period by the architect Biagio Rossetti. The intervention is located in the private entrance leading to the residence on the piano nobile. The project involved the complete demolition of the existing concrete staircase to insert a lift in the void, with a new staircase rethought for its new use. The new staircase structure was designed entirely in steel, consisting of a central blade (ceiling-to-floor) 15 mm thick which, beyond being load-bearing, also acts as a balustrade. The step frames are anchored to the blade and serve as a tray to hold the marble slab acting as the tread. Along the staircase perimeter, a sheet-metal stringer receives and anchors the other side of the step. The flooring was made entirely from the recovery of the Verona Biancone marble used in the previous staircase. Wall-grazing lights illuminate the stairwell, while two pendant lights illuminate the lift shaft."
  },
  "it-ferrara-casa-vignolo": {
    titolo: "CASA VIGNOLO",
    descrizione: "The renovation takes place in the historic centre of Ferrara and, more specifically, in its medieval part. The intervention is located in an interior portion of the building. The project underwent a complete reorganisation in plan. Structurally, partial work was carried out on the internal and external load-bearing masonry to allow new openings. Architecturally, the residential unit was entirely revisited. The dwelling features at its entrance a space linking the living area to the kitchen area and on to the lounge area. The living area is fitted with furniture in close dialogue with the corridor, making the space more than a mere connection between the bathroom and the sleeping area. The bathroom is the result of an alternation of white and black tones, on both floor and walls, blending into part of the furniture. The sleeping area contains a walk-in wardrobe and a bed using the same materials as the rest of the furniture. All the wooden ceilings were painted white to make the spaces brighter — spaces which are heavily penalised by the unfortunate northward exposure of the entrance wall and the bathroom/sleeping zone, set within a small internal courtyard. All the furniture was made of black MDF and phenolic fir. The entrance bookcase is in metal. The lighting was designed using lamps from the Castaldi brand, using two models: a tube-shaped lamp positioned both horizontally and vertically in the living, kitchen and walk-in wardrobe areas, and recessed lamps for the corridor and bathroom. The bedroom is illuminated by the Pilastro lamp. The entire flooring was made of polished concrete with underfloor radiant heating."
  },
  "it-ferrara-casa-anselmo": {
    titolo: "CASA ANSELMO",
    descrizione: "The renovation takes place within a wing of the historic palace built by Biagio Rossetti in the late fifteenth century, today listed under heritage protection. More specifically, the intervention is located on the top floor adjoining the palace attic. The project underwent a complete reorganisation in plan. Structurally, partial work was done on the slabs and perimeter masonry. Architecturally, the residential unit was entirely revisited. The dwelling features a single space with kitchen and living area, connected via a corridor / walk-in wardrobe to the bathroom and the bedroom. On the ceiling, the decorated wooden tie beams of the trusses were exposed, part of an old coffered ceiling. The flooring used is of two types: industrial parquet and concrete. All lighting was supplied by Viabizzuno. The furniture in the living room, bedroom and bathroom was custom-designed and made of MDF. For winter conditioning, underfloor radiant heating was installed; for summer conditioning, a heat-pump system with concealed split units was used."
  },
  "chine": {
    titolo: "CASA CHINE'",
    descrizione: "The renovation takes place within a wing of a historic palace from the early sixteenth century, today listed under heritage protection. More specifically, the intervention is located in an attic in the rear wing of the palace. As a result of the earthquake, one wing of the building suffered considerable damage, leading to structural deficiencies. The project therefore included a complete structural consolidation to reduce seismic vulnerability and a total reorganisation in plan. Structurally, work was carried out on both the floor slabs and the perimeter masonry with minimally invasive systems, agreed with the heritage authority. Architecturally, the two residential units were entirely revisited. The first features a large living room hosting a kitchen and lounge area. This space then communicates with the sleeping area through a flush-with-the-wall door leading to a small corridor. The second features a lowered entrance space directly linking the living and sleeping areas. The flooring materials are natural oak combined with a cement-grey stoneware. Some areas of the apartments feature level differences for architectural-functional and systems-related reasons. All conditioning is underfloor. The ceilings were all made in plasterboard following the slope of the roof pitches."
  },
  "it-ferrara-palazzo-mazzucchi": {
    titolo: "CELESTE",
    descrizione: "The intervention concerns only the bathroom area of an apartment. The apartment is located inside a fifteenth-century palace — more precisely, Palazzo Bevilacqua-Mazzucchi, built by the famous Renaissance architect-urbanist Biagio Rossetti. To create the new bathroom, complete demolition of the existing one was chosen, including floors, screeds and partitions. The new layout splits the single room into two spaces. The first hosts the less intimate area with the washbasins and storage. The second, more intimate, houses the toilet and bidet with adjoining bath-shower, reached by a step. The sanitaryware is by Flaminia, while the taps are Bossini. The wall facing the washbasins and the shower was made entirely using the \"microtopping\" method, with cement mortar pigmented in light blue, achieving full waterproofing of the wall. Ceilings and walls were made of plasterboard. The flooring is entirely in aged oak laid with glue on a new screed. A careful study of lighting, with luminaires designed by Peter Zumthor, highlights bespoke furniture entirely made of full-paste black MDF."
  },
  "gelichi": {
    titolo: "CORE",
    descrizione: "The apartment subject to renovation is located inside a fifteenth-century palace — more precisely, Palazzo Bevilacqua-Mazzucchi, built by the famous Renaissance architect-urbanist Biagio Rossetti. The project concerns only part of the apartment — more precisely, the union of two spaces previously used as corridors. The client's need was to obtain within the home a space that could be dedicated both to archiving numerous books and to reading them. We therefore proceeded to create a single space that could be both a reading area and at the same time a filter-connection zone for all the other rooms of the apartment, becoming the \"heart\" of the home. To achieve this, the central wall dividing the two old corridors was demolished. Subsequently, the old reed-mat ceiling was entirely demolished to bring back to light the decorated tie beams of the existing, authentic Palladian-style trusses. The new ceiling was made of plasterboard, creating within it two new cones of light to bring direct lighting into the new reading space. All the exposed tie beams were highlighted through a careful restoration with minor pictorial restoration touches. To emphasise these decorations in the evening, a series of incandescent spotlights was installed, creating a museum-like effect."
  },
  "it-ostiglia-housing": {
    titolo: "RESIDENCE LA CIMINIERA",
    descrizione: "The project is located in an area adjacent to the Po river embankment in Ostiglia. A private road provides access to the eight new dwellings arranged in a line. The design strategy was to make the front opposite the road the main front, hosting the everyday living spaces (dining-lounge-kitchen). Compositionally, the dwellings appear as a pairing of two volumes. A first independent volume in brick, and a second in white plaster marking the junction with the neighbouring home. The street-front elevation is characterised by the presence of a void generating the entrance to the dwelling and a series of three long windows illuminating, respectively, a study area and the main bedroom on the first floor. The garden-front elevation resolves itself into a telescope-like opening generated by the steep slope of the roof. This glazed framing offers a spectacular view from the living area onto the private garden adjacent to the Po embankment. Inside, the dwelling hosts on the ground floor a kitchen connected with a dining-lounge area, a bathroom, a study, and a garage. On the first floor are a main bedroom with walk-in wardrobe, a single room with terrace or indirect overlook onto the living area, and a bathroom. The façade materials used are red brick and plaster installed using a ventilated external thermal insulation system, ensuring effective energy savings."
  },
  "uk-preston-case-popolari": {
    titolo: "TRABOCCHI",
    descrizione: "The approach to the project theme was made considering not only the area assigned by the competition brief, but the whole block in relation to the neighbouring green areas. Through several questions we asked ourselves, we tried to justify our design strategy. How can we, at the urban scale of the site, find a way to mend the connective fabric? Our answer comes through a statement: empty spaces must be considered a non-renewable resource. To pursue this statement, we began analysing all the scattered green areas around the site with the intent of reintegrating them into a single large green element. Having this public green lung runs against the programme requested by the brief. To satisfy that, we asked: how can we maintain this public greenery without burdening the residents? We created an intervention strategy in which an extra floor is built to be offered to people with higher income, who can therefore pay a higher rent that covers the maintenance costs of the green area, and to transform the old urban scheme into a new concept featuring a single street-facing front, allowing an increase in greenery. How can all the residents of the new intervention enjoy a private green area? Thanks to long balconies, the residents of the upper floors can enjoy the public greenery embracing their terraces, transforming them into small hanging gardens. To meet the requirement of parking spaces within the area, micro dunes of 1.5 m were created, easily hiding cars from the pedestrian routes. The public green area is thus bounded on one side by the green dunes and on the other by a \"ha-ha\" system that defines the boundary between public and private greenery for the ground-floor apartments."
  },
  "it-castelmassa-ro-appartm": {
    titolo: "THE GARDEN",
    descrizione: "The new intervention on the historic property \"Il Giardino\" focuses on the complete recovery of the authentic historic façade, bringing back to light its original material and regular rhythm of openings, as documented historically. To preserve the authentic façade openings, it was not possible to insert a vertical-circulation core on the front facing the square that would also adequately distribute the new apartments. The new project was therefore tackled through a gallery solution. The gallery acts as a filter between the old façade and the rest of the building, which is rethought in a modern key. The gallery is the element that keeps people always in direct contact with the square and, at the same time, ensures privacy from the adjacent outdoor space dedicated to the commercial activity (restaurant). Large glazings open onto the new south façade facing the gallery to bring large amounts of direct and indirect light into the apartments. The new south façade is clad in white-painted brick that climbs the entire façade, wraps around the roof and descends along the north façade. Volumetrically, all the additions at the rear of the building were demolished — additions that were the result of hasty and inappropriate refurbishments dictated by the needs of past years. The new project proposes a commercial space on the ground floor with access from the square and an adjoining private outdoor area, and 4 duplex apartments of various sizes on the remaining two floors. All apartments are accessible from the south and north fronts."
  },
  "it-francolino-fe-villa": {
    titolo: "ZANGOB",
    descrizione: "The concept underlying the design of the villa began in relation to an existing reinforced concrete structure, in line with an original project. The commission was to rethink the entire house, adding greater volume compared to the old project. The house is conceived as an intersection of two distinct masses. The first is characterised by the white volume representing the living space, and the second is the roof which embraces and covers the entire habitable space and, at certain points, also becomes the skin of the building. The north elevation was kept as closed as possible to ensure more privacy, as another house faces it. The south elevation, by contrast, hosts large glazings. Wooden brises-soleil cover the large windows facing the garden, filtering the direct sunlight. The living area is an extension of the previous volume of the old project. With its volume, it juts out from the main villa volume with the intent of pushing the living and dining rooms toward the garden."
  },
  "it-occhiobello-ro-appartamen": {
    titolo: "THE SAIL",
    descrizione: "The project is located in a town near Ferrara. It is part of a new subdivision. The building regulations limit the new residential volumes to a maximum height of 13 m and they can house between two and four apartments. The building was conceived in a duplex typology to allow each apartment its own night zone on the upper level. The smaller apartments [A] are on the ground floor with an adjoining private garden and a ground-floor bathroom. The B apartments are accessed on the first floor, opening directly onto the living room and connected via three steps to the kitchen-dining area. Part of the lounge is a double-height space overlooking a study-lounge area on the upper floor. The lounge is lit by two large 6-metre-tall windows facing west-north-east. On the upper floor, in addition to the study space, there are two bedrooms, a bathroom and a storeroom. The building is covered by a light roof with an adjoining aluminium frame intended to give a sail-like effect, sheltering the building from wind and sun. To make the duplex typology immediately clear, two different materials were used: natural stone and white plaster. Large Cor-Ten frames surround the windows both inside and out."
  },
  "nl-almere-villa": {
    titolo: "JUST TWO WALLS",
    descrizione: "The layout refers to a pure form par excellence: the square. The volume generated by it was then raised from the ground by means of pillars to a height allowing a full perception of the surroundings. The raised volume also refers to the parallelism between tree trunks/pillars and tree canopy/dwelling. Part of the volume was raised to a greater height to highlight the access and to identify an area usable by car. Two reinforced-concrete load-bearing walls further define the access area and, in plan, the distribution zone within the house. The zone generated between the two walls connects three functional bands: night zone – service zone – day zone. Two main axes divide the plan: the distribution axis between the service area and the night area, and the circulation axis bounded by the two reinforced-concrete walls. The piles holding the house above the ground are the ideal extension of the foundation piles, highlighting the construction technique of Dutch foundations. Reinforced concrete is the cornerstone material of the project, exalted in its massiveness by the glazed surface enveloping it. To insert the project more strongly within the \"wood\" context, part of it was allowed to penetrate the structure via a courtyard, which at the same time acts as a filter element between night and day zones."
  },
  "ghost": {
    titolo: "GHOST",
    descrizione: "Additional information GHOST category: furniture designer: Rudy Davi client: self-produced year of realisation: 2015 text: Ghost is a coat-stand made from a steel tube and a series of cords of different lengths to which hooks and hangers are attached. Its use is therefore versatile: from hanging a garment to hanging a bag. The effect is that of floating objects, like ghosts."
  },
  "fan": {
    titolo: "FAN",
    descrizione: "Additional information FAN category: furniture location: Udine designer: Rudy Davi project team: Federico Gamarro client: Promosedia 2013 competition year of realisation: 2013 text: Fan chair was born from a careful research into the union of form and mechanics. The defining feature of the seat is the particular mechanical joint linking the leg-seat-backrest structure. This joint, when released, allows the three elements to rotate until they overlap like a fan, producing a handy object that can easily be grasped and carried. A white-enamelled metal leg, also rotatable, gives the chair the unique effect of a suspended seat."
  },
  "otto": {
    titolo: "OTTO",
    descrizione: "Additional information OTTO category: lighting designer: Rudy Davi client: self-produced photo: Rudy Davi year of realisation: 2014 text: Otto is a lamp that re-establishes a manual approach between the user and the object. The electric cable becomes the fundamental element of the system. By grasping and winding the cord between two steel bollards fixed to the wall, one can adjust the height of the light. This is achieved through two fixed pulleys on the ceiling. A steel connecting rod precisely regulates the height of the light. An incandescent bulb sits in a chromed bulb-holder. A wide range of cord colours makes the object customisable according to need."
  },
  "20m": {
    titolo: "20M",
    descrizione: "Additional information 20M category: furniture designer: Rudy Davi client: Vulpinari Federici Commercialisti photo: Rudy Davi year of realisation: 2013 text: Slimness is what this object aims to communicate. 20 mm is the height of the perimeter profile of the structure, creating the load-bearing element to hold a black MDF top. Four legs with variable section complete the steel structure, subsequently painted white."
  },
  "scent-memories": {
    titolo: "SCENT MEMORIES",
    descrizione: "Additional information SCENT MEMORIES category: competition prize: not significant location: Austin, USA designer: Rudy Davi project team: Federico Gamarro year of realisation: 2013 text: How can we have the sensation that our deceased loved ones are still beside us? Every person has their own scent. Scents have the enormous potential to take us back into memory in a way no other sense can. The impact of scents on our memory is closely linked to the process of the amygdala and hippocampus in our brain, which control memories. The new tombstone design has the ability to physically envelop us with its structure, emanating the perfume of the deceased and making us feel embraced by them. The tombstone is made of steel. Above it sits an urn that releases drops of the deceased's essence onto the metal surface. The goal is to artificially recreate the same essence the person emitted in life, and dissolve it on the surface of the tombstone."
  },
  "weekly": {
    titolo: "WEEKLY",
    descrizione: "Additional information WEEKLY category: furniture designer: Rudy Davi client: self-produced exhibitions: Mantovacreativa, Mantova 2013 photo: Rudy Davi year of realisation: 2013 text: An object whose intent is to catalogue the personal habits of the week. Seven drawers allow the user to organise their week, each one representing a single day. A calamine iron structure houses the central wooden core. The slender legs of the structure fully reveal the central body in its complete slimness and materiality. The entire wooden body is made of full-paste black MDF and subsequently veneered with natural oak."
  },
  "archita": {
    titolo: "ARCHITA",
    descrizione: "Additional information ARCHITA category: lighting prize: OPENDESIGNITALIA 2012 selection designer: Rudy Davi client: self-produced exhibitions: Arredamente, Ferrara 2012; OpenDesignItalia, Venice 2012; Mantovacreativa, Mantova 2013 photo: Matteo Cattabriga year of realisation: 2012 text: Archita is a lamp that aims to re-establish a dialogue between object and human. Performing a tiring and unusual gesture like the one needed to operate this lamp awakens in the user a deeper reflection on the meaning of everyday gestures. The intent is to make people reflect on the simplicity of small things. It is made from a steel tube with four vertical cuts. The light source is housed in the base. A bronze-steel piston slides inside the tube via a cord and pulley. The result is a manual light-intensity modulator. By pulling the cord, the piston rises and falls inside the tube, varying the luminous section and consequently the direction of the light."
  },
  "klava": {
    titolo: "KLAVA",
    descrizione: "Additional information KLAVA category: lighting prize: winner LEXUS DESIGN AWARD 2012 designer: Rudy Davi client: not realised exhibitions: Museo della Permanente, Milan 2013 publications: Al Volante year of realisation: 2012 video: award ceremony text: It is an object of great versatility, since it can be oriented in infinite positions according to the user's needs, maintaining that precise position. Thanks to a physical-mechanical study of the operating system, the lamp can be grasped and placed in various positions and remain in the chosen position. A combination of masses produced a striking object. The weights at play are those of a large steel sphere within the base and a metal cap with its own mass, on which the sphere can rotate. The result is the stability of the object in its infinite positions thanks to the friction force generated between the masses at play. A Teflon element, acting as a counterweight sliding along the vertical rod, allows the calibration of forces when the bulb is replaced with one of greater or lesser weight."
  },
  "lc": {
    titolo: "LC",
    descrizione: "Additional information LC category: furniture designer: Rudy Davi client: self-produced exhibitions: OpenDesignItalia, Bologna 2011; Arredamente, Ferrara 2012 photo: Matteo Cattabriga year of realisation: 2011 text: A table conceived from the union and interlocking of L and C shapes. A structure built entirely with L-profiles in calamine iron joined by welding. The structure is formed by two C-shaped portals subsequently linked by an adjustable joint. The structure houses a C-shaped tray made of an MDF core covered in white Corian, fitting flush within the structure. With this system, the tray can be interchanged with a series of colours while keeping the structure unchanged."
  },
  "acca": {
    titolo: "ACCA",
    descrizione: "Additional information ACCA category: furniture designer: Rudy Davi client: self-produced exhibitions: Fuorisalone, Milan 2010; OpenDesignItalia, Bologna 2011; Arredamente, Ferrara 2012 photo: Rudy Davi year of realisation: 2010 text: The Acca chair was born from a simple dual-use concept. It can be turned 180° to obtain a new Acca chair which, while keeping the same form, has a different surface finish. The structure is made of OSB wood, while the veneer is velvet. It can also be rotated by 90°, becoming a module for building a customisable bookcase. In case of need — for example for guests — the bookcase can be dismantled to obtain extra chairs."
  },
  "cherry": {
    titolo: "CHERRY",
    descrizione: "Additional information CHERRY category: furniture designer: Rudy Davi client: not realised year of realisation: 2005 text: The Cherry chair takes its cue from the natural form of the cherry. To ensure a comfortable seat, the seat can flex. The chair is made from a single element produced with a mould. The design material is plexiglass."
  },
  "pilastro-lamp": {
    titolo: "PILASTRO",
    descrizione: "Additional information PILASTRO category: lighting prize: 3rd place BEEH DESIGN CONTEST 2010 designer: Rudy Davi client: self-produced exhibitions: OpenDesignItalia, Modena 2010; Fuorisalone, Milan 2011; OpenDesignItalia, Bologna 2011; Mantovacreativa, Mantova 2013 publications: Interni no. 618 photo: Fabio Angiuli year of realisation: 2004 video: video text: \"Surrealism, lightness, plasticity and versatility are the elements that characterise the Pilastro lamp. A self-adjusting compression device allows the lamp to be positioned between floor and ceiling, giving it a floating appearance. The central body of the lamp is formed by two connected tubes. To install Pilastro, one grasps the central body with both hands, sets the lower part of the device on the floor and pushes downward. The structure lowers just enough to allow vertical insertion between floor and ceiling. A steel ring is fixed at the upper and lower part of the lamp. Between the two rings the fabric is positioned. With a simple compression gesture of the rod inside the fabric, we can effortlessly move the lamp; rotating the steel ring at the lower part of the lamp, the cylindrical form transforms into a double inverted cone. Increasing and decreasing brightness, changing the form and colour of the fabric allow us to transform the lamp, obtaining — in every respect — objects of different design according to our desires.\""
  }
};
